@using RecipeShare.Models
@using RecipeShare.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - Recipe Share</PageTitle>

<h1>Submit a Recipe</h1>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

@if (SubmitSuccess)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe has been added to the community.
        <a href="/recipe/@SubmittedId">View it here</a>.
    </div>
}

<EditForm Model="NewRecipe" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="NewRecipe.Title" placeholder="e.g. Grandma's Apple Pie" />
        <ValidationMessage For="() => NewRecipe.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="NewRecipe.Category">
            <option value="">-- Select a category --</option>
            <option value="Breakfast">Breakfast</option>
            <option value="Lunch">Lunch</option>
            <option value="Dinner">Dinner</option>
            <option value="Desserts">Desserts</option>
        </InputSelect>
        <ValidationMessage For="() => NewRecipe.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="NewRecipe.Ingredients"
                       placeholder="2 cups flour&#10;1 cup sugar&#10;..." />
        <ValidationMessage For="() => NewRecipe.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="NewRecipe.Steps"
                       placeholder="1. Preheat oven to 350°F&#10;2. Mix ingredients&#10;..." />
        <ValidationMessage For="() => NewRecipe.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-success">Submit Recipe</button>
</EditForm>

@code {
    private Recipe NewRecipe { get; set; } = new();
    private bool SubmitSuccess { get; set; }
    private int SubmittedId { get; set; }

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(NewRecipe);
        SubmittedId = NewRecipe.Id;
        SubmitSuccess = true;
        NewRecipe = new();
    }
}

